Data.Script:
var list = [];
try { list = JSON.parse(vars.tt_raw || "[]"); } catch (e) { list = []; }
var max = parseInt(vars.maxTargets || "3", 10);
var id = String(vars.elementId);
var i = list.indexOf(id);
var msg;
if (i >= 0) { list.splice(i, 1); msg = "Unmarked. Targets: " + list.length + "/" + max; }
else if (list.length >= max) { msg = "Already " + max + " targets: click a marked one to unmark it first."; }
else { list.push(id); msg = "Marked. Targets: " + list.length + "/" + max; }
return { tt_json: JSON.stringify(list), tt_msg: msg };
